def load_observed_fragments(root,data_uri):
 root=Path(root).resolve();p=root/'chiikawa-pets/limited-previews/observed-fragments.json'
 if not p.exists():return {}
 config=json.loads(p.read_text());require(config==EXPECTED,'Unreviewed sparse fragment metadata/geometry/scope')
 result=copy.deepcopy(config)
 for entry in result.values():
  for f in entry['frames']:
   p=(root/safe_relative(f['assetPath'])).resolve();require(p.is_relative_to(root),'Observed fragment outside project');raw=p.read_bytes()
   require(raw[:8]==b'\x89PNG\r\n\x1a\n' and hashlib.sha256(raw).hexdigest()==f['assetSha256'] and list(struct.unpack('>II',raw[16:24]))==f['assetSize'],'Unreviewed observed fragment pixels/dimensions')
   f['source']=data_uri(p)
 return result
